export const diffusionMeta={slug:'models/diffusion',title:'Diffusion and Score-Based Generation',description:'Connect Gaussian corruption, posterior denoising, scores and reverse dynamics; distinguish solver acceleration, trajectory consistency and generator distribution matching.',date:'2026-06-11',updated:'2026-10-24',topicPath:['models'],tags:['diffusion','DDPM','DDIM','score matching','SDE','ODE','consistency','progressive distillation','SiD','shortcut models','Flow Generator Matching'],kind:'dense-topic',prototype:true,visibility:'public',learningGoals:['Derive a noise-prediction sampler','Separate conditional targets from the marginal field','Choose an acceleration objective with explicit gradient and cost contracts'],related:['post-training/distillation','training/objectives','math/probability','math/calculus','execution/speculation']};
