export const diffusionSections=[['question','What does the generator learn?'],['notation','Keep time, variance and state separate'],['forward','Construct the forward Markov chain'],['marginal','Sample any training noise level directly'],['forward-animation','Watch signal disappear without confusing paths'],['prior','When is terminal noise a valid prior?'],['posterior','Reverse with the clean datum: a tractable target'],['learned-reverse','Remove the clean datum from the reverse model'],['noise-loss','Why noise prediction trains a denoiser'],['variational','The VAE view and the variational bound'],['score','A score differentiates log density'],['conditional','Conditional targets recover a marginal score'],['score-experiment','Inspect ambiguity between two clean values'],['parameterization','Change prediction coordinates, not the probability path'],['weighting','Equivalent outputs need not mean equivalent losses'],['continuous','Pass from a chain to continuous dynamics'],['reverse-sde','Reverse time without reversing the noise sign'],['probability-flow','Same marginals, different sample paths'],['endpoint-animation','A trajectory endpoint is not a denoising mean'],['likelihood','Density requires the flow divergence'],['sampling','Separate ancestral sampling and deterministic updates'],['solver-experiment','See numerical error in a known field'],['errors','Identify which error more steps can reduce'],['paired-distillation','Compress a chosen noise-to-sample coupling'],['progressive','Replace two teacher steps with one student step'],['consistency','Learn the common endpoint of a trajectory'],['consistency-boundary','Enforce the positive-time boundary'],['consistency-training','Distillation and training construct different targets'],['consistency-evidence','Read the consistency experiments with their settings'],['consistency-continuous','A continuous pseudo-objective is not a loss metric'],['consistency-implementation','Connect the consistency equations to released code'],['flow-matching','Derive velocity from the declared interpolation'],['shortcut','Learn displacements at multiple step sizes'],['shortcut-training','Build a shortcut target without changing its meaning'],['shortcut-evidence','Read shortcut quality against its sampling budget'],['score-distillation','Match distributions without teacher rollouts'],['sid','SiD requires a gradient contract, not just a norm'],['sid-gradient-example','Why equal score losses can give different gradients'],['sid-recipe','Keep the two SiD update distributions separate'],['sid-implementation','Translate SiD’s loss into the released update'],['sid-evidence','Read SiD quality and stability with their settings'],['fgm','Flow Generator Matching retains the missing gradient'],['fgm-gradient','See which generator gradient field matching misses'],['fgm-evidence','Separate FGM theory from the image-training recipe'],['corruptions','The broader corruption view has different mathematics'],['choice','Choose the change that addresses the bottleneck'],['implementation','Small kernels and necessary checks'],['history','A chronology with parallel acceleration branches'],['sources','Sources and connected topics']];
const p=x=>'<p>'+x+'</p>',code=x=>'<pre tabindex="0" role="region" aria-label="Code example"><code>'+x.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')+'</code></pre>';
const table=(caption,heads,rows)=>baseTable(caption,heads,rows).replace('class="dense-table-wrap"','class="dense-table-wrap" tabindex="0" role="region" aria-label="'+caption+'"');
const papers={ddpm:'https://arxiv.org/abs/2006.11239',sde:'https://arxiv.org/abs/2011.13456',ddim:'https://arxiv.org/abs/2010.02502',progressive:'https://arxiv.org/abs/2202.00512',consistency:'https://arxiv.org/abs/2303.01469',sid:'https://arxiv.org/abs/2404.04057',shortcut:'https://arxiv.org/abs/2410.12557',fgm:'https://arxiv.org/abs/2410.19310'};
export function diffusionReader(link){const scenes=diffusionScenes(),parts=[],related=(slug,label)=>"<a href='"+link(slug)+"'>"+label+'</a>',add=(id,body)=>parts.push(section(id,diffusionSections.find(s=>s[0]===id)[1],body));
 const pdFirst=ddimStep(.25,.5,1,0),pdSecond=ddimStep(.5,.81,pdFirst.next,1),pdTarget=progressiveTarget(.25,.81,1,pdSecond.next);
 add('question',p('A diffusion model does not learn to recover every original image from arbitrary noise. That recovery is impossible when corruption removes information. It learns conditional predictions that support sampling from a data distribution.')+p('The fixed forward process creates training examples at known noise levels. The model learns a local denoising field. A reverse sampler then uses that field repeatedly to transform a simple prior into structured samples.')+p('This distinction explains both the strength and the cost of diffusion. Local targets are available without solving the whole generation problem during training. Generation still requires a sequence of model evaluations. Acceleration can change the numerical solver, the learned trajectory map, or the generator objective. These are different interventions.')+p('Start with Gaussian diffusion. The broader corruption view comes later, after the equations have a clear domain. This note owns diffusion-specific sampling and distillation; '+related('post-training/distillation','Distillation')+' owns the general teacher–student framework.'));
 add('notation',table('Symbols used below',['Symbol','Meaning','Important condition'],[['x₀','Clean data vector','An image, latent or other continuous vector'],['xₜ','Noisy state at level t','Same dimensionality as x₀'],['βₜ / αₜ','Step variance / 1−βₜ','Discrete DDPM coefficients'],['ᾱₜ','Product of α₁…αₜ','Not a variance or standard deviation'],['aₜ / σₜ','Signal and noise amplitudes',inlineMath(String.raw`x_t=a_tx_0+\sigma_t\epsilon`)],['ε','Independent standard Gaussian noise','Same shape as the data'],['sθ(x,t)','Learned marginal score','Vector field in data coordinates'],['h / d','Numerical step or shortcut length','Not a training-noise variance']])+p('For variance-preserving marginals, '+inlineMath(String.raw`a_t^2+\sigma_t^2=1`)+'. Additive-noise examples instead use '+inlineMath(String.raw`a_t=1`)+'. Do not transfer formulas between conventions without the signal coefficient. Batch inputs usually have shape [B,C,H,W] for images or [B,N,D] for latent patches. Broadcast one sampled time per example across its data coordinates.'));
 add('forward',eq(String.raw`\begin{aligned}q(x_t\mid x_{t-1})&=\mathcal N(\sqrt{1-\beta_t}\,x_{t-1},\beta_t I)\\x_t&=\sqrt{\alpha_t}\,x_{t-1}+\sqrt{\beta_t}\,z_t\end{aligned}`,'0<βₜ<1; independent zₜ∼N(0,I). The schedule is fixed in this setup.')+p('Each transition reduces the previous signal and adds new Gaussian noise. The conditional dependence is Markov: the next state depends on the current state, not the complete earlier sequence.')+p('For one coordinate, the conditional mean follows the signal multiplier. The accumulated variance satisfies '+inlineMath(String.raw`v_t=\alpha_t v_{t-1}+\beta_t`)+' with '+inlineMath(String.raw`v_0=0`)+'. The recurrence gives '+inlineMath(String.raw`v_t=1-\bar\alpha_t`)+'. This algebra is the reason that direct training samples are available; it is not an approximation that requires tiny steps.')+p('The noise variables at different Markov transitions are independent. A visualization that reuses one ε across levels displays marginal couplings, not an actual realization of this Markov chain.'));
 add('marginal',eq(String.raw`\begin{aligned}\bar\alpha_t&=\prod_{s=1}^t\alpha_s\\q(x_t\mid x_0)&=\mathcal N(\sqrt{\bar\alpha_t}\,x_0,(1-\bar\alpha_t)I)\\x_t&=\sqrt{\bar\alpha_t}\,x_0+\sqrt{1-\bar\alpha_t}\,\epsilon\end{aligned}`,'One independent ε can sample the chosen marginal at t.')+p('Training samples a clean datum, a noise level, and ε. The formula creates xₜ in one operation. It does not simulate x₁ through xₜ₋₁. This makes the training target inexpensive even when the generation schedule has many levels.')+p('For a constant '+inlineMath(String.raw`\beta=0.08`)+', after ten steps '+inlineMath(String.raw`\bar\alpha=0.92^{10}\approx0.4344`)+'. With x₀=2, the conditional mean is about 1.318 and the conditional variance about .5656. These are distribution moments. A single noisy draw also includes its particular ε.')+p('Store or compute the schedule at sufficient precision. Summing log α avoids losing small products; using expm1 can accurately recover 1−ᾱ near zero noise. The exact implementation still needs its schedule endpoints and broadcasting rules.'));
 add('forward-animation',scenes.forward+p('The five dots use assigned standardized positions, not sampled images. Moving the stage changes the conditional Gaussian centered around one clean value. The figure explains signal contraction and variance growth without pretending to train or run a neural network.')+p('Read the coefficients separately. The noise standard deviation approaches one, while the signal coefficient approaches zero. The mean reaches zero only in the limiting schedule shown by the formula, not at every finite terminal level.'));
 add('prior',p('Generation starts from a distribution we can sample. In a conventional variance-preserving schedule, the chosen prior is N(0,I). The forward terminal distribution approaches that prior when ᾱT is sufficiently small and residual scaled data structure is negligible.')+p('A finite schedule with ᾱT>0 still contains signal. The marginal q(xT) is generally a mixture over clean data, not exactly N(0,I). If the terminal signal is large, training and generation begin from different distributions.')+p('There are two separate checks: the schedule must reach the intended noise regime, and the reverse model must handle states drawn from its inference prior. Increasing the number of steps alone does not establish either check. A zero-terminal-signal construction needs endpoint-safe parameterization.'));
 add('posterior',eq(String.raw`\begin{aligned}q(x_{t-1}\mid x_t,x_0)&=\mathcal N(\widetilde\mu_t,\widetilde\beta_t I)\\\widetilde\mu_t&=\frac{\sqrt{\bar\alpha_{t-1}}\beta_t}{1-\bar\alpha_t}x_0\\&\quad+\frac{\sqrt{\alpha_t}(1-\bar\alpha_{t-1})}{1-\bar\alpha_t}x_t\\\widetilde\beta_t&=\frac{\beta_t(1-\bar\alpha_{t-1})}{1-\bar\alpha_t}\end{aligned}`,'The clean datum makes this forward posterior analytically tractable.')+p('Multiply the Gaussian likelihood of xₜ given xₜ₋₁ by the Gaussian marginal of xₜ₋₁ given x₀. Complete the square in xₜ₋₁. The precisions add; the precision-weighted means determine μ̃ₜ.')+p('The formula is not yet a generator. At inference, x₀ is unknown. Its role is to supply a training target and a tractable variational comparison. At t=1, the conditional posterior knows x₀ exactly and '+inlineMath(String.raw`\widetilde\beta_1=0`)+'; the model decoder remains a separate distributional choice.')+p('Do not replace the unknown marginal reverse conditional q(xₜ₋₁|xₜ) with this clean-conditioned posterior. Integrating over possible x₀ values can produce a non-Gaussian mixture. '+cite(papers.ddpm,'DDPM, equations 6–7')+' gives the posterior.'));
 add('learned-reverse',eq(String.raw`\begin{aligned}p_\theta(x_{0:T})&=p(x_T)\prod_{t=1}^T p_\theta(x_{t-1}\mid x_t)\\p_\theta(x_{t-1}\mid x_t)&=\mathcal N(\mu_\theta(x_t,t),\Sigma_\theta(x_t,t))\end{aligned}`,'Learned reverse transitions do not receive the original clean datum.')+p('The model supplies a mean and either fixed or learned variance. Small-step reverse Gaussian approximations are useful, but a coarse step can cross an ambiguous or multimodal region. A Gaussian parameterization does not make that ambiguity disappear.')+eq(String.raw`\begin{aligned}\mu_\theta(x_t,t)&=\frac1{\sqrt{\alpha_t}}\left(x_t-\frac{\beta_t\epsilon_\theta(x_t,t)}{\sqrt{1-\bar\alpha_t}}\right)\\x_{t-1}&=\mu_\theta(x_t,t)+\sigma_{\mathrm{rev},t}z\end{aligned}`,'σrev,ₜ is the chosen reverse standard deviation; it is not the forward marginal σₜ.')+p('The network predicts noise, but the sampler converts that prediction into a reverse mean. Randomness is a separate operation. The final decoder convention and whether noise is added on the last step must be explicit.'));
 add('noise-loss',eq(String.raw`L_{\mathrm{simple}}=\mathbb E_{x_0,t,\epsilon}\!\left[\left\lVert\epsilon-\epsilon_\theta(a_tx_0+\sigma_t\epsilon,t)\right\rVert^2\right]`,'The expectation includes the declared distribution over noise levels.')+p('The injected ε is known, so the target is available. The model cannot infer the particular noise perfectly from an ambiguous xₜ. Under squared error, its population optimum is E[ε|xₜ,t], not the unknowable noise realization in every training pair.')+p('That conditional average is sufficient for the corresponding marginal score. A denoiser is therefore useful even when its direct clean prediction would average multiple possible images. Iterative generation uses the whole field and its evolution, not one mean estimate at maximum noise.')+p('Reduction over coordinates changes the scale of the gradient. Averaging versus summing, time weights, and the sampling distribution over t are part of the loss contract. Report them before comparing two training runs.'));
 add('variational',p('The forward chain is a fixed approximate inference process. The reverse chain is a learned latent-variable model. This resembles a VAE with many latent layers indexed by noise level. The autoregressive structure runs across levels, not necessarily pixels or text tokens.')+eq(String.raw`\begin{aligned}\mathbb E[-\log p_\theta(x_0)]&\le\mathbb E\Bigl[D_{\mathrm{KL}}(q(x_T\mid x_0)\Vert p(x_T))\\&\quad+\sum_{t=2}^T D_{\mathrm{KL}}\bigl(q(x_{t-1}\mid x_t,x_0)\Vert p_\theta(x_{t-1}\mid x_t)\bigr)\\&\quad-\log p_\theta(x_0\mid x_1)\Bigr]\end{aligned}`,'The outer expectation is over data and the forward chain q(x₁:T|x₀). Prior mismatch, intermediate reconstruction terms and final decoder form the negative variational bound.')+p('For a fixed reverse variance, an intermediate Gaussian KL becomes a weighted squared error between posterior and model means. Substituting the noise parameterization gives a time-dependent weight on noise-prediction error. The simplified unweighted noise loss changes those weights. It is not numerically identical to the complete negative ELBO.')+p('The latent-variable interpretation connects diffusion to variational inference. It does not imply that a learned reverse chain has competitive exact likelihood whenever it produces attractive samples. '+related('math/information','Information Theory')+' separates coding objectives from sample-quality judgments.')+p('DDPM Figure 5 plots reconstruction RMSE on a [0, 255] scale against reverse steps and received bits per dimension. The distortion drops rapidly at low coding rates in this CIFAR10 experiment. This is a progressive reconstruction result, not a sampling-speed benchmark. A pleasing generated image and a short lossless code therefore remain separate evaluation targets. '+cite('https://arxiv.org/pdf/2006.11239v2#page=7','DDPM Figure 5')+'.'));
 add('score',eq(String.raw`s_t(x)=\nabla_x\log p_t(x)`,'The score is a vector, not a probability, reward, classifier logit or scalar likelihood.')+p('The gradient indicates the local direction of increasing log density. A normalization constant independent of x disappears under differentiation. A vector field can therefore be learned without explicitly evaluating the density everywhere.')+p('For a Gaussian N(m,σ²I), the score is (m−x)/σ². It points toward the mean and increases in magnitude as the same displacement becomes less plausible under a smaller variance. A score describes a local density geometry; following it once is not a general sampling algorithm.')+p('At positive Gaussian noise, discrete empirical clean samples become a smooth mixture. At zero noise, a density or its ordinary gradient may cease to exist. Endpoint limits require care.'));
 add('conditional',eq(String.raw`\begin{aligned}q(x_t\mid x_0)&=\mathcal N(a_tx_0,\sigma_t^2I)\\\nabla_{x_t}\log q(x_t\mid x_0)&=-\frac{x_t-a_tx_0}{\sigma_t^2}=-\frac{\epsilon}{\sigma_t}\\\nabla_{x_t}\log p_t(x_t)&=\mathbb E[\nabla_{x_t}\log q(x_t\mid x_0)\mid x_t]\end{aligned}`,'Differentiate the marginal mixture under regularity that permits exchanging integration and differentiation.')+p('A training pair supplies the conditional score. Squared-error regression averages that target over the clean posterior q(x₀|xₜ). The result is the marginal score required for generation. The conditional target and the learned marginal field are related, but they are not the same vector on every pair.')+p('The posterior weighting is essential. Clean samples that explain the current observation contribute more. Averaging scores over the unconditional training-data distribution would generally yield the wrong field.')+eq(String.raw`a_t\mathbb E[x_0\mid x_t]=x_t+\sigma_t^2s_t(x_t)`,'For additive noise '+inlineMath(String.raw`a_t=1`)+', this is the denoising posterior-mean identity.')+p('The score and denoising average encode the same conditional information at interior noise levels. That identity follows directly from the conditional Gaussian derivative.'));
 add('score-experiment',scenes.score+p('At x=0, the equal-prior clean values −2 and +2 are equally plausible. The posterior mean is zero. No clean example in this constructed dataset equals zero. A good squared-error denoiser can thus return a value outside the clean support.')+p('Increase the observation toward +2. Its likelihood shifts posterior mass toward the positive clean value. Increasing σ weakens that evidence. The marginal score changes because both component directions and posterior weights change.')+p('This is not proof that diffusion generation averages its output modes. It explains why a local denoising estimate and a final generated sample are different objects.'));
 add('parameterization',eq(String.raw`\begin{aligned}x_t&=a_tx_0+\sigma_t\epsilon\\\widehat x_0&=\frac{x_t-\sigma_t\widehat\epsilon}{a_t},\quad\widehat s=-\frac{\widehat\epsilon}{\sigma_t}\\v&=a_t\epsilon-\sigma_tx_0\\\widehat x_0&=a_tx_t-\sigma_t\widehat v\\\widehat\epsilon&=\sigma_tx_t+a_t\widehat v\end{aligned}`,'The v inverse assumes '+inlineMath(String.raw`a_t^2+\sigma_t^2=1`)+'. Divisions require nonzero coefficients.')+p('The coordinates describe the same noisy marginal. A model can predict clean data, noise, score, or a velocity-like linear combination. The sampler must convert the chosen output using the actual schedule.')+p('At very low signal, dividing by aₜ amplifies error. At very low noise, dividing by σₜ amplifies error. A mathematically invertible interior transformation can still be numerically poor near an endpoint.')+p('The symbol v is overloaded across papers. The linear combination above is not automatically the instantaneous velocity of any arbitrary flow-matching interpolation. Check the path definition before transferring a velocity target.')+p('A model output is not automatically a score. The released VP and sub-VP wrappers negate the network output and divide by the corruption standard deviation. The VE wrapper instead treats the network output as the score. Time labels also differ between continuous and discrete models. Inspect the wrapper before applying another conversion, or the sign and scale can be applied twice. '+cite('https://github.com/yang-song/score_sde/blob/main/models/utils.py','Released Score-SDE output wrappers')+'.'));
 add('weighting',eq(String.raw`\begin{aligned}\lVert\widehat s-s_{\mathrm{target}}\rVert^2&=\frac{\lVert\widehat\epsilon-\epsilon\rVert^2}{\sigma_t^2}\\\lVert\widehat x_0-x_0\rVert^2&=\frac{\sigma_t^2}{a_t^2}\lVert\widehat\epsilon-\epsilon\rVert^2\end{aligned}`,'These are training-pair errors with '+inlineMath(String.raw`s_{\mathrm{target}}=-\frac{\epsilon}{\sigma_t}`)+', not errors against the marginal score on every pair. Predictions are converted at one fixed interior noise level.')+p('Uniform score error therefore emphasizes a different set of times than uniform noise error. Uniform clean error changes the emphasis again. Equivalence of representations does not establish equivalence of finite-capacity training objectives.')+p('Time sampling, explicit weights, output preconditioning, and coordinate reduction jointly determine the effective objective. An importance-sampled time distribution needs compensating weights if the intended integral is unchanged. Otherwise it intentionally changes the objective.')+p('Check the total scale as well as relative weighting. A batch of large images and a batch of small latents can have different summed errors despite the same per-coordinate prediction quality. '+related('training/objectives','Losses and Objectives')+' owns the general reduction rules.')+p('The released continuous loss has two weighting branches. One multiplies the score residual by corruption standard deviation before squaring. The likelihood-weighted branch instead weights the squared score residual by diffusion amplitude squared. These are different training objectives, not just different names for the same sampler. The later likelihood-weighting reference is distinct from the original paper’s recommended weighting. '+cite('https://github.com/yang-song/score_sde/blob/main/losses.py','Released Score-SDE losses')+'.'));
 add('continuous',eq(String.raw`dX=f(X,t)\,dt+g(t)\,dW`,'Forward time increases from clean data toward noise. g is a scalar isotropic diffusion amplitude here.')+p('An SDE describes both drift and stochastic variation. A variance-preserving example uses '+inlineMath(String.raw`f(x,t)=-\beta(t)x/2`)+ ' and '+inlineMath(String.raw`g(t)=\sqrt{\beta(t)}`)+'. The nonnegative rate beta controls signal attenuation and noise injection. A variance-exploding additive-noise process instead has zero drift and growing noise variance.')+p('The time coordinate need not equal noise standard deviation or log signal-to-noise ratio. Reparameterizing time changes coefficients. A solver step in t cannot be replaced by the same number in σ without applying the chain rule.')+p('The continuous formulation links discrete denoising chains and score-based generation. It also exposes different numerical sampling choices without changing the target field. '+cite(papers.sde,'Score-Based Generative Modeling through SDEs')+' gives this framework.')+p('Sub-VP keeps the VP signal attenuation but injects less noise. Define '+inlineMath(String.raw`B_t=\int_0^t\beta(u)\,du`)+ ' for a nonnegative rate. Both processes multiply the clean state by '+inlineMath(String.raw`e^{-B_t/2}`)+'. Their clean-conditioned variances differ:')+table('Continuous Gaussian corruption choices',['Process','Clean-conditioned mean','Clean-conditioned variance'],[['VE','Unchanged clean state',inlineMath(String.raw`\sigma(t)^2-\sigma(0)^2`)],['VP','Attenuated clean state',inlineMath(String.raw`1-e^{-B_t}`)],['Sub-VP','Same attenuation as VP',inlineMath(String.raw`(1-e^{-B_t})^2`)]])+p('These variances condition on a fixed clean state; they are not the total data-population variance. Sub-VP uses diffusion amplitude '+inlineMath(String.raw`\sqrt{\beta(t)(1-e^{-2B_t})}`)+'. Simply swapping a sampler while retaining VP corruption targets would not train this process. '+cite('https://arxiv.org/html/2011.13456v2','Score-SDE Appendix B')+'.')+p('For integrated beta log(2) and clean value 2, both means are '+vpMarginal(Math.log(2),2).mean.toFixed(4)+'. VP conditional variance is '+vpMarginal(Math.log(2),2).variance.toFixed(2)+', while sub-VP variance is '+vpMarginal(Math.log(2),2,'sub-vp').variance.toFixed(2)+'. This is an analytic example, not a quality comparison. For positive finite integrated beta, sub-VP has smaller conditional variance. Both variances approach one as integrated beta grows without bound.')+p('The VE variance difference assumes a smooth schedule with its stated initial noise. The paper’s practical geometric schedule treats time zero separately and solves above a positive cutoff. Likewise, “variance preserving” means unit population covariance stays unit under VP; it does not mean every dataset variance is constant.')+p('In the released implementation, marginal_prob returns a mean and a standard deviation. Square its second output before comparing with the variance table. For sub-VP, this output equals the VP variance, but its role is still a standard deviation. The practical VE implementation uses its geometric sigma directly as the corruption standard deviation. It does not subtract the initial sigma squared. Match that corruption convention when reproducing training. '+cite('https://github.com/yang-song/score_sde/blob/main/sde_lib.py','Released Score-SDE marginal definitions')+'.'));
 add('reverse-sde',eq(String.raw`dX=[f(X,t)-g(t)^2s_t(X)]\,dt+g(t)\,d\overline W`,'Integrate from T toward 0: dt is negative. Reverse Brownian variance uses |dt|.')+p('For a decreasing grid, write '+inlineMath(String.raw`\Delta t=t_{\mathrm{next}}-t<0`)+'. The deterministic update multiplies the complete reverse drift by that negative value. The random increment scales with '+inlineMath(String.raw`\sqrt{|\Delta t|}`)+', not '+inlineMath(String.raw`\sqrt{\Delta t}`)+'.')+p('An implementation can instead use increasing reverse time '+inlineMath(String.raw`\tau=T-t`)+'. Then the drift changes sign to '+inlineMath(String.raw`-f+g^2s`)+'. Both conventions are valid; mixing their signs is not.')+p('The displayed formula assumes state-independent isotropic diffusion. General matrix or state-dependent diffusion needs the appropriate covariance and additional terms. A formula copied from this setting is not a universal SDE reversal recipe.')+ '<h3>Condition the score at the current noise level</h3>'+p('Bayes’ rule gives '+inlineMath(String.raw`\nabla_x\log p_t(x\mid y)=\nabla_x\log p_t(x)+\nabla_x\log p_t(y\mid x)`)+'. For class labels, train the classifier on corrupted labeled examples at each noise level. Differentiate its log probability with respect to the noisy input, then add that gradient to the unconditional score. A classifier trained only on clean images does not supply the required noisy likelihood. '+cite('https://arxiv.org/html/2011.13456v2','Score-SDE §5 and Appendix I.1')+'.')+p('Exact conditional reversal also needs the appropriate terminal conditional distribution. Starting from the usual unconditional prior is justified only when terminal noise sufficiently removes information about the condition. Multiplying the classifier gradient by a different strength changes the target; it is not unchanged Bayesian conditioning.')+p('For inpainting, the paper draws the observed coordinates from their forward-corrupted distribution and evaluates the unconditional score on the combined state. Only the unknown coordinates are evolved. This is an approximation to clean-observation conditioning, not a proof of exact posterior sampling. Colorization applies an orthogonal channel transform, completes unknown channels, then transforms back. Orthogonality preserves isotropic Gaussian noise. '+cite('https://arxiv.org/html/2011.13456v2','Score-SDE Appendix I.2–I.4')+'.'));
 add('probability-flow',eq(String.raw`dX=\left[f(X,t)-\tfrac12g(t)^2s_t(X)\right]dt`,'The probability-flow ODE shares time marginals with the forward SDE under the exact score and regularity assumptions.')+p('The factor one half is not optional. The ODE replaces stochastic spreading with a deterministic transport whose continuity equation gives the same density evolution. It does not replicate individual Brownian trajectories.')+p('The result is distributional: the ensemble at each time has the same marginal law. It does not identify which original clean datum produced a given noisy training observation. Approximate neural scores and finite numerical steps can break exact equivalence.')+p('Do not remove randomness from a reverse SDE update and call the result the probability-flow ODE. Its drift also changes. Likewise, a deterministic sampler is not necessarily a literal Euler discretization in the same time coordinate.'));
 add('endpoint-animation',scenes.flow+p('In the constructed Gaussian process, the exact score is '+inlineMath(String.raw`-\frac{x}{1+t}`)+'. The probability-flow velocity is '+inlineMath(String.raw`\frac{x}{2(1+t)}`)+'. Its trajectory satisfies '+inlineMath(String.raw`x(t)=z\sqrt{1+t}`)+', so its clean endpoint is z.')+p('At t=4 and z=1, '+inlineMath(String.raw`x=\sqrt5\approx2.2361`)+'. The trajectory endpoint is 1, while the Bayesian denoising mean is '+inlineMath(String.raw`\frac{x}{5}\approx0.4472`)+'. These are both correct answers to different questions. The observed noisy state could have arisen from many clean samples.')+p('A consistency map should preserve the trajectory endpoint as t changes. Training it only to reproduce the clean posterior mean defines a different function. This distinction is the basis of the later consistency section.')+p('Read DDPM Figures 6 and 14 as clean-image predictions along a sampled reverse chain, not as the noisy states themselves. Coarse structure appears before fine detail in these examples. Figure 7 instead fixes an intermediate latent and runs several stochastic completions. Those completions can share structure without producing identical pixels. These are different views of generation, not proof that a posterior mean is a trajectory endpoint. '+cite('https://arxiv.org/pdf/2006.11239v2#page=7','DDPM Figures 6–7 and 14')+'.'));
 add('likelihood',eq(String.raw`\begin{aligned}\frac d{dt}\log p_t(x(t))&=-\operatorname{div}b(x(t),t)\\\log p_0(x_0)&=\log p_T(x_T)+\int_0^T\operatorname{div}b(x(t),t)\,dt\end{aligned}`,''+inlineMath(String.raw`b=f-\frac12g^2s`)+'; the path transports x₀ forward to xT in this convention.')+p('A smooth, well-defined flow supports the instantaneous change-of-variables formula. Density evaluation requires integrating both the state and the divergence. A high-dimensional Jacobian trace may need a stochastic estimator.')+p('The resulting value is the likelihood of the modeled flow, not proof that the learned field equals the data distribution. Numerical tolerance, trace estimation, preprocessing and discrete versus continuous data conventions still matter.')+p('This capability is distinct from fast sample generation. A one-step student can generate quickly while lacking a tractable exact density. Compare sample quality and likelihood as separate measurements.')+p('The Skilling–Hutchinson estimator avoids constructing the full Jacobian. Draw a zero-mean probe with identity covariance, such as independent signs. Compute a vector–Jacobian product, then contract it with the same probe. Its expectation is the divergence; a single draw is not generally exact. '+cite('https://arxiv.org/html/2011.13456v2','Score-SDE Appendix D.2')+'.')+p('For a synthetic two-dimensional linear field, let the Jacobian be '+inlineMath(String.raw`J=\begin{pmatrix}2&3\\0&0\end{pmatrix}`)+'. Its trace is 2. For independent sign probes '+inlineMath(String.raw`z=(z_1,z_2)^\mathsf{T}`)+', the estimate '+inlineMath(String.raw`z^\mathsf{T}Jz=2+3z_1z_2`)+ ' is either −1 or 5. Averaging all four sign pairs gives 2. The estimator can fluctuate even when the field is known exactly.')+p('The paper uses RK45 with absolute and relative tolerances of '+inlineMath(String.raw`10^{-5}`)+ ' for likelihood evaluation. It averages five test-set runs and stops at a positive time cutoff. Table 2 evaluates uniformly dequantized CIFAR-10; its starred discrete DDPM entries are ELBO bounds. These conventions matter when comparing bits per dimension. More probes reduce trace-estimation noise, but do not remove solver, cutoff or model error. '+cite('https://arxiv.org/html/2011.13456v2','Score-SDE Table 2 and Appendix D.2')+'.')+p('The released likelihood routine draws one Gaussian or sign probe per data point and keeps it fixed throughout the ODE solve. Resampling inside each derivative evaluation would give the adaptive solver a randomly changing right-hand side. It integrates from a positive cutoff toward the prior, then adds the integrated divergence to the terminal log density. Its bits-per-dimension conversion includes the inverse data-scaling correction. This correction depends on the data representation; it is not a universal offset. '+cite('https://github.com/yang-song/score_sde/blob/main/likelihood.py','Released Score-SDE likelihood routine')+'.'));
 add('sampling',p('Why can the denoiser stay unchanged? DDIM preserves the clean-conditioned noisy marginals while changing their joint coupling across levels. The usual noise-prediction surrogate sees those marginals. However, identical weighted-loss optima are justified for separately parameterized levels; a finite shared network can respond differently to loss weights. Deterministic sampling is a limiting construction, not a positive-variance ELBO identity. '+cite('https://arxiv.org/html/2010.02502v4','DDIM §3–4')+'.')+table('Different reverse updates',['Choice','What is held fixed?','What changes?'],[['Ancestral DDPM','Learned denoiser and forward schedule','Draw from Gaussian reverse transitions'],['Deterministic DDIM','Compatible noise/clean prediction','Follow a non-Markovian deterministic update'],['Probability-flow solver','Continuous score and ODE convention','Numerical transport with half-score drift'],['Predictor–corrector','Noisy marginals and score','Alternate trajectory advance and stochastic correction']])+eq(String.raw`\begin{aligned}x_s&=a_s\widehat x_0+\sigma_s\widehat\epsilon\\\widehat\epsilon&=\frac{x_t-a_t\widehat x_0}{\sigma_t}\end{aligned}`,`Deterministic DDIM-style update, ${inlineMath(String.raw`s<t`)}. Use a compatible schedule and output conversion.`)+p('The deterministic update retains the current inferred noise direction while changing signal and noise amplitudes. It can skip levels. It is not the operation of setting reverse variance to zero in every ancestral DDPM formula.')+p('Stochasticity is neither automatically harmful nor automatically better. Its effect depends on score accuracy, numerical discretization and the sampling objective. '+cite(papers.ddim,'DDIM')+' introduces the non-Markovian construction.')+p('For a scalar example, take current cumulative alpha 0.25, target cumulative alpha 0.64, state 1 and predicted noise 0.5. DDIM predicts clean state '+ddimStep(.25,.64,1,.5).clean.toFixed(4)+', then combines signal '+ddimStep(.25,.64,1,.5).signal.toFixed(4)+' with retained noise '+ddimStep(.25,.64,1,.5).noise.toFixed(4)+'. The next state is '+ddimStep(.25,.64,1,.5).next.toFixed(4)+'. The corresponding ancestral mean with no fresh draw is '+ancestralStep(.64,1-.25/.64,1,.5,0).mean.toFixed(4)+': removing randomness alone does not produce DDIM. These are synthetic scalar calculations, not image-quality measurements.')+p('In the released DDIM sampler, index −1 denotes the clean endpoint: a prepended zero beta makes its cumulative alpha equal one. The generalized branch does not clip the clean prediction; the separate DDPM branch does. Match the branch, not just the repository name. '+cite('https://github.com/ermongroup/ddim/blob/main/functions/denoising.py','Released DDIM update code')+'.')+p('Inspect the actual timestep sequence. The released uniform runner uses integer division to choose its stride. Requesting 60 steps from 1,000 levels produces 63 indices, ending at 992 rather than 999. Rounded quadratic indices can repeat. A new implementation should validate ordered indices, actual evaluation count and its starting prior; do not silently equate requested steps with executed steps. '+cite('https://github.com/ermongroup/ddim/blob/main/runners/diffusion.py','Released DDIM sequence selection')+'.')+p('DDIM Figures 5 and 9 hold the initial latent fixed while changing the sampling schedule. Similar high-level structure is an observed property of these examples, not exact equality between schedules. Figure 4 reports hours for 50,000 images on one Nvidia 2080 Ti; that timing is not a universal speedup. '+cite('https://arxiv.org/pdf/2010.02502v4#page=8','DDIM Figures 4–5 and 9')+'.')+'<h3>Predict time, then correct at the new level</h3>'+p('In the paper’s predictor–corrector procedure, the predictor advances to the next noise level. The corrector then runs score-based MCMC at that fixed level. Each corrector iteration evaluates the score again after changing the state. This is not Heun: Heun combines slopes to integrate a trajectory.')+code(langevinStep.toString())+p('This tested scalar kernel uses a fixed positive step, the current score and an independent standard-normal draw z. It does not advance diffusion time. The paper also describes norm-based step selection; this kernel does not implement that adaptive rule. '+cite('https://arxiv.org/html/2011.13456v2','Score-SDE §4.2 and Appendix G')+'.')+p('A finite Langevin step is approximate even with an exact score. For a standard-normal target, score equals minus the state. Starting at variance one, step 0.1 gives variance 1.01 after one update. This synthetic moment calculation shows discretization bias, not a neural-model result. More correction costs more score evaluations; compare samplers at equal evaluation budgets.')+p('In Score-SDE Figure 9, rows change total score evaluations; columns change corrector steps per level. Compare within a row to inspect budget allocation. Table 1’s 2,000-step predictor baseline also requires interpolation of a model trained at 1,000 discrete levels. The paper tunes corrector strength and adds final denoising. Its favorable PC results are not a guarantee that correction always helps. '+cite('https://arxiv.org/pdf/2011.13456v2#page=23','Score-SDE Figure 9 and Appendix G')+'.')+p('The released PC loop applies the corrector at the current time, then applies the predictor. With final noise removal enabled, it returns the last predictor mean rather than its random sample. Its adaptive Langevin step uses score and noise norms averaged across samples and devices; this is not independent per-example normalization. Keep operation order, norm reduction and final noise removal explicit when reproducing a sampler. '+cite('https://github.com/yang-song/score_sde/blob/main/sampling.py','Released Score-SDE sampler')+'.'));
 add('solver-experiment',scenes.solver+p('Euler uses the current slope once. Heun predicts a provisional endpoint, evaluates another slope, then averages the two slopes. In this toy field, Heun reduces error per step but spends twice as many field evaluations.')+p('Compare at equal evaluations as well as equal step counts. Four Heun steps and four Euler steps do not have the same field-call budget. Higher formal order does not eliminate a wrong learned score, an incompatible schedule or an unstable step size.')+p('The exact exponential is available only because the demonstration uses a known scalar field. No plotted line represents FID, prompt fidelity, neural training or measured serving latency.'));
 add('errors',table('Three sources of mismatch',['Source','Example','Will more numerical steps fix it?'],[['Model error','Learned score points in the wrong direction','Not by itself'],['Integration error','Coarse solver deviates from its known ODE','Often, within stability and smoothness conditions'],['Distribution/conditioning error','Wrong prior, guidance or deployment prompts','Not automatically']])+p('Local reverse predictions can be easier to learn than a global noise-to-data map. However, a larger number of training levels does not universally make every target easier or improve sample quality monotonically. Noise schedule, model capacity and objective determine that behavior.')+p('Inference cost depends on number of field evaluations, model cost, guidance calls, batching, memory traffic and the decoder. A nominal one-step sampler may still run an encoder or decoder and more than one network branch. Count the complete workflow.'));
 add('paired-distillation',eq(String.raw`\begin{aligned}z&\sim p_{\mathrm{prior}},\quad y=\operatorname{TeacherSampler}(z,c)\\L_{\mathrm{pair}}&=\mathbb E[\lVert G_\theta(z,c)-y\rVert^2]\end{aligned}`,'c is optional conditioning. Declare teacher randomness, solver, guidance and latent coordinate system.')+p('This approach learns a particular coupling between input noise and teacher outputs. Generating targets can be expensive, whether stored offline or recomputed during training. The student must approximate a much larger transport operation than one local denoising step.')+p('A deterministic teacher assigns one target to each exact input. Squared error does not inherently average different teacher modes for that same input. Averaging occurs when the target remains random conditional on the student input, or when the student lacks information or capacity.')+p('If teacher randomness matters, include its seed/noise in the student input or choose an objective that matches a distribution. A reproducible target convention is part of the algorithm, not merely a dataset detail.'));
 add('progressive',p('Progressive distillation starts from a deterministic teacher. It builds a target whose single student update reaches the same state as two teacher updates. The trained student becomes the next teacher, and the schedule is halved again.')+eq(String.raw`\begin{aligned}N&\to N/2\to N/4\to\cdots\to1\\y&=\operatorname{TeacherStep}(\operatorname{TeacherStep}(x_t,t\to u),u\to s)\\\widetilde x_0&=\frac{y-(\sigma_s/\sigma_t)x_t}{a_s-(\sigma_s/\sigma_t)a_t}\end{aligned}`,'Invert one deterministic DDIM step; the denominator must be nonzero. The last line is an algebraic target, not a clean-data label.')+p('For a power-of-two schedule, 64→32→16→8→4→2→1 takes six reductions. Each stage trains a model; six reductions do not mean six minibatches. Non-power-of-two schedules require an explicit partition and endpoint convention.')+p('The method preserves local teacher behavior before demanding a full one-step map. Teacher errors and student approximation errors can propagate across stages. '+cite(papers.progressive,'Progressive Distillation')+' supplies the staged procedure.')+ '<h3>One student target, two teacher evaluations</h3>'+p('Consider a synthetic scalar example with cumulative alpha squared 0.25 → 0.50 → 0.81. Start from state 1. The first teacher predicts clean value 2; the second predicts clean value 1 at the new state. Those predictions need not agree.')+table('Two teacher updates become one student update',['Operation','Clean prediction','Resulting state'],[['Teacher: 0.25 → 0.50','2',pdFirst.next.toFixed(4)],['Teacher: 0.50 → 0.81','1',pdSecond.next.toFixed(4)],['Student: 0.25 → 0.81',pdTarget.clean.toFixed(4),pdTarget.next.toFixed(4)]])+p('The effective student prediction is neither teacher prediction. Substituting that target into one DDIM update reproduces the teacher endpoint. A trained student only approximates this target. The numbers are computed from the scalar kernels; they are not image-quality measurements.')+'<h3>Construct the training pair before changing the schedule</h3>'+p('The original procedure still samples training data and corrupts it on the student’s discrete time grid. It does not require full teacher rollouts, but it is not data-free. Initialize the student from the teacher. Evaluate the frozen teacher twice, with the second evaluation at the first predicted state. Stop gradients through the target. After training this stage, promote the student to teacher.')+p('Each student specializes to its trained grid. Arbitrarily changing inference times is not the same as evaluating the original continuous denoiser. The paper keeps teacher and student architectures the same; its main speed gain is fewer evaluations, not fewer parameters.')+'<h3>Keep the pure-noise prediction well defined</h3>'+p('The paper includes an exactly zero-signal terminal level. Ordinary noise-to-clean conversion divides by signal amplitude and becomes singular there. Direct clean prediction or the velocity coordinates defined earlier avoid that division. Noise-error weighting also gives zero clean-reconstruction weight at zero signal-to-noise ratio (SNR). The paper instead examines weights '+inlineMath(String.raw`\max(\mathrm{SNR},1)`)+ ' and '+inlineMath(String.raw`1+\mathrm{SNR}`)+'. Both retain nonzero weight at pure noise.')+p('These choices do not make every output and weighting combination stable. The undistilled CIFAR-10 ablation reports divergence for noise output with truncated-SNR weighting. Treat parameterization, weighting and time sampling as a coupled design. '+cite('https://arxiv.org/html/2202.00512v2','Progressive Distillation §3–5 and Appendix G')+'.')+p('The main comparisons retain useful quality at four or eight sampling steps, with more degradation at one or two. The stochastic baseline is tuned separately for each step budget. CIFAR-10 curves average four seeds; the larger datasets use one run. These conditions do not establish universal quality preservation or a universal training-cost saving. The original schedule trains 50,000 updates per stage, and 100,000 for the final two- and one-step stages; faster schedules trade training cost against quality. '+cite('https://arxiv.org/html/2202.00512v2','Progressive Distillation §5.2 and Appendices E–I')+'.')+ '<h3>Match the released endpoint convention</h3>'+p('The released JAX code uses finite cosine log-SNR bounds, rather than exact zero signal and zero noise. Training samples an integer index uniformly on the student grid. The teacher midpoint is halfway in schedule time, not halfway in cumulative alpha squared.')+p('Both teacher calls and the student training prediction are unclipped. The lowest-index target is explicitly replaced by the second teacher’s clean prediction. The sampler likewise returns the clean prediction on its last step. Applying the ordinary finite-bound DDIM formula there gives a slightly different endpoint. '+cite('https://github.com/google-research/google-research/blob/master/diffusion_distillation/diffusion_distillation/dpm.py','Released target and sampler')+'; '+cite('https://github.com/google-research/google-research/blob/master/diffusion_distillation/diffusion_distillation/schedules.py','Released schedule')+'.')+p('The released CIFAR configuration predicts clean data with truncated-SNR loss. Its log-SNR bounds are −20 and 20. Evaluation clips the clean estimate; training does not. Distillation disables dropout and parameter averaging in this configuration. These settings are reproduction details, not requirements for every distillation method. '+cite('https://github.com/google-research/google-research/blob/master/diffusion_distillation/diffusion_distillation/config/cifar_distill.py','Released CIFAR distillation configuration')+'.'));
 add('consistency',eq(String.raw`\begin{aligned}F(x_t,t)&=F(x_s,s)=x_\varepsilon\\F(x,\varepsilon)&=x\end{aligned}`,'ε here denotes the minimum positive time, not a Gaussian noise vector.')+p('A consistency function maps every point on a trajectory to its common near-clean endpoint. The endpoint belongs to the ODE coupling. It is not generally the original datum used to create a noisy training pair.')+p('Self-consistency alone allows a useless constant function. The boundary condition prevents that solution by requiring identity behavior at the minimum time. A skip-connected parameterization can enforce this exactly.')+eq(String.raw`\begin{aligned}F_\theta(x,t)&=c_{\mathrm{skip}}(t)x+c_{\mathrm{out}}(t)N_\theta(x,t)\\c_{\mathrm{skip}}(\varepsilon)&=1,\quad c_{\mathrm{out}}(\varepsilon)=0\end{aligned}`,'The coefficients ground the endpoint while the network learns the interior map.')+p('One-step generation samples the appropriate terminal prior and applies Fθ once. Few-step consistency sampling can revisit intermediate levels. More evaluations may improve fidelity, but the result depends on the trained model and sampling procedure.'));
 add('consistency-boundary',p('Appendix C shifts the skip and output numerators by the positive cutoff. The output denominator still contains t, not t−ε.')+eq(String.raw`\begin{aligned}c_{\mathrm{skip}}(t)&=\frac{\sigma_{\mathrm{data}}^2}{(t-\varepsilon)^2+\sigma_{\mathrm{data}}^2}\\c_{\mathrm{out}}(t)&=\frac{\sigma_{\mathrm{data}}(t-\varepsilon)}{\sqrt{\sigma_{\mathrm{data}}^2+t^2}}\end{aligned}`,inlineMath(String.raw`t\ge\varepsilon>0`)+'; '+inlineMath(String.raw`\sigma_{\mathrm{data}}>0`)+'. The paper uses '+inlineMath(String.raw`\sigma_{\mathrm{data}}=0.5`)+' and '+inlineMath(String.raw`\varepsilon=0.002`)+'.')+table('Computed boundary coefficients, not measured model outputs',['Noise standard deviation t','Skip coefficient','Network coefficient'],[.002,.1,1,80].map(t=>[String(t),(.25/((t-.002)**2+.25)).toFixed(6),(.5*(t-.002)/Math.hypot(.5,t)).toFixed(6)]))+p('At the cutoff, the skip is one and the network coefficient is zero. The output is therefore the input, regardless of network weights. '+cite('https://arxiv.org/html/2303.01469v2#A3','Consistency Models Appendix C')+'.'));
 add('consistency-training',eq(String.raw`L_{\mathrm{CD}}=\mathbb E\!\left[\lambda(t)d\left(F_\theta(x_t,t),\operatorname{stopgrad}(F_{\theta^-}(\widehat x_s,s))\right)\right]`,'x̂ₛ is a neighboring point produced by the teacher ODE solver; θ− can be an EMA target network.')+p('Consistency distillation uses a pretrained denoising teacher to connect neighboring states. The loss compares endpoint predictions, not the states themselves. The target branch is stopped while the online model updates.')+p('Consistency training instead constructs learning targets from data without a pretrained diffusion teacher. Its estimator and discretization analysis are method-specific. It is not exact teacher integration performed without a teacher, nor generic independent noise-pair regression.')+p('Noise levels, distance function, target-network update and boundary coefficients jointly define training. '+cite(papers.consistency,'Consistency Models')+' distinguishes training and distillation. Neither consistency equality nor an EMA update alone establishes distributional fidelity.')+ '<h3>Reuse the noise, not a claimed ODE trajectory</h3>'+p('For teacher-free consistency training, sample a datum and one Gaussian noise vector. Use that same vector at neighboring noise levels. In this section, time equals noise standard deviation; it is not the VP cumulative alpha coordinate.')+eq(String.raw`\begin{aligned}x_t&=x+t z,\quad x_s=x+s z,\quad z\sim\mathcal N(0,I),\quad 0<\varepsilon\le s<t\\L_{\mathrm{CT}}&=\mathbb E\!\left[\lambda(s)d\!\left(F_\theta(x_t,t),\operatorname{stopgrad}(F_{\theta^-}(x_s,s))\right)\right]\end{aligned}`,'x is sampled training data; z is reused in both branches. Sample neighboring indices, update the online model, then update its target average.')+p('The conditional score estimate is negative noise divided by its standard deviation. Substituting this estimate into one backward Euler update gives the shared-noise lower state. The score identity holds after conditioning and averaging. It does not identify each training pair with an exact ODE path.')+table('Shared noise is not the exact probability-flow path',['Lower-state construction','Value at noise level 1'],[['Shared-noise pair: datum 1, noise 1 at level 2',consistencyPair(1,1,2,1).low.toFixed(4)],['Euler update with true marginal score −3/5','1.8000'],['Exact Gaussian probability-flow endpoint',(3*Math.sqrt(2/5)).toFixed(4)]])+p('This synthetic example uses standard-normal training data. The high state is 3. The three lower states differ even with an exact score. The shared-noise pair is a training construction, not an image-generation experiment.')+p('The original asymptotic argument assumes an exact marginal score, Euler updates, smooth target and distance functions, bounded derivatives and weighting, and finite score moments. Taylor expansion makes the expected first-order terms agree as the grid is refined. Unbiased scores do not make nonlinear losses exactly equal at finite spacing. '+cite('https://arxiv.org/html/2303.01469v2','Consistency Models §5 and Appendix A.3')+'.')+p('Multistep inference is different: predict an endpoint, inject fresh noise to a lower chosen level, then predict again. It does not apply the endpoint map repeatedly to an unchanged noisy state.'));
 add('consistency-evidence',p('The main experiments initialize consistency distillation (CD) from pretrained EDM diffusion weights and consistency training (CT) randomly. Both use the learned perceptual similarity metric LPIPS and Rectified Adam, without warmup, learning-rate decay or weight decay. LPIPS receives bilinear 224×224 inputs on CIFAR-10/ImageNet, not LSUN.')+table('CIFAR-10, Table 1: FID is lower-is-better; NFE counts model evaluations, not latency',['Method','NFE','FID'],[['CD','1','3.55'],['CD','2','2.93'],['CT','1','8.70'],['CT','2','5.83']])+p('Seed-aligned sample grids illustrate coupling, not absence of mode collapse. Editing panels use an LSUN Bedroom CD model with inference-time constraints, not task-specific training. '+cite('https://arxiv.org/html/2303.01469v2#S6','Consistency Models §6, Table 1 and Appendices C–E')+'.'));
 add('consistency-continuous',p('Appendix B’s stopped-target continuous objectives are pseudo-objectives: their gradients define training, but their values do not measure convergence. Its CT comparison initializes both variants from EDM; it is not the random-initialized main experiment. '+cite('https://arxiv.org/html/2303.01469v2#A2','Consistency Models Appendix B')+'.'));
 add('consistency-implementation',p('The released PyTorch implementation covers ImageNet-64 and LSUN; CIFAR-10 uses a separate JAX repository. Its flag named <code>distillation</code> selects boundary coefficients for both consistency training and distillation. '+cite('https://github.com/openai/consistency_models/blob/e32b69ee436d518377db86fb2127a3972d0d8716/README.md','Released repository scope')+'.')+p('The raw U-Net output is not the endpoint prediction. Scale the noisy input before the network; then combine the network output with the skip path.')+eq(String.raw`\begin{aligned}c_{\mathrm{in}}(t)&=\frac1{\sqrt{t^2+\sigma_{\mathrm{data}}^2}}\\\tau_{\mathrm{net}}&=250\log(t+10^{-44})\end{aligned}`,'Multiply the noisy state by the input coefficient; pass the rescaled time to the network. Noise levels stay positive.')+table('Keep the three model roles distinct',['Role','Used for','Updates'],[['Frozen diffusion teacher','Heun neighboring target in CD','No parameter update'],['Consistency target','Stopped endpoint target in CD and CT','Target EMA after a successful optimizer step'],['Evaluation EMA','Sampling checkpoint selection','Separate averaging rate']])+p('The released CT launch examples supply <code>teacher_model_path</code>. The entry point copies those weights into the online model, but the CT loss branch does not receive the diffusion teacher. Teacher-free targets do not imply random initialization. '+cite('https://github.com/openai/consistency_models/blob/e32b69ee436d518377db86fb2127a3972d0d8716/scripts/cm_train.py','Pinned training entry point')+'; '+cite('https://github.com/openai/consistency_models/blob/e32b69ee436d518377db86fb2127a3972d0d8716/cm/train_util.py','Pinned training loop')+'.')+'<h3>Count evaluations, not schedule entries</h3>'+table('Released ImageNet CD example: steps=40, indices [0,22,39]',['Index','Noise level','Action'],[['0','80.000000','First endpoint prediction'],['22',((80**(1/7)+22/39*(.002**(1/7)-80**(1/7)))**7).toFixed(6),'Second endpoint prediction'],['39','0.002000','Terminal marker; no extra prediction']])+p('Each pair predicts an endpoint, then adds fresh noise for the next selected level. The final marker ideally adds zero noise; floating-point schedule arithmetic can leave a tiny residual. Three indices require two network calls. Sampling clips the denoised output by default; training does not.')+p('This scalar reference uses explicit strictly decreasing levels within [0.002,80]. The last entry defines the exact cutoff. Callbacks must return finite scalars. It is not the released tensor implementation or a trained generator:')+code("from math import sqrt\ndef cm_sample(endpoint, x, levels, indices, normal):\n    if len(levels)<2 or any(not 0.002<=s<=80 for s in levels): raise ValueError(\"levels\")\n    if any(b>=a for a,b in zip(levels, levels[1:])): raise ValueError(\"decreasing levels\")\n    if any(type(i) is not int for i in indices): raise ValueError(\"integer indices\")\n    if len(indices)<2 or indices[0]!=0 or indices[-1]!=len(levels)-1: raise ValueError(\"endpoints\")\n    if any(b<=a for a,b in zip(indices, indices[1:])): raise ValueError(\"increasing indices\")\n    cutoff = levels[-1]\n    for a,b in zip(indices, indices[1:]):\n        x = endpoint(x, levels[a])\n        x += sqrt(levels[b]**2-cutoff**2)*normal()\n    return x")+p(cite('https://github.com/openai/consistency_models/blob/e32b69ee436d518377db86fb2127a3972d0d8716/cm/karras_diffusion.py','Pinned loss, wrapper and sampling implementation')+'.')+'<h3>Verify the recipe wiring before a run</h3>'+p('In this pinned revision, the training entry point does not forward <code>loss_norm</code> to the denoiser constructor. Selecting an L2 CLI flag alone therefore retains default LPIPS. The loop condition remains true when <code>lr_anneal_steps</code> is zero, even after <code>total_training_steps</code>. Check both paths before copying a launch command. '+cite('https://github.com/openai/consistency_models/blob/e32b69ee436d518377db86fb2127a3972d0d8716/cm/script_util.py','Pinned constructor and defaults')+'; '+cite('https://github.com/openai/consistency_models/blob/e32b69ee436d518377db86fb2127a3972d0d8716/scripts/launch.sh','Pinned launch examples')+'.'));
 add('flow-matching',p('A probability-flow ODE comes from the diffusion field. Flow matching can instead start from a chosen interpolation and regress its velocity directly. Define the endpoints before using any velocity formula:')+eq(String.raw`\begin{aligned}x_t&=(1-t)x_0+t\epsilon,\quad \epsilon\sim\mathcal N(0,I)\\u_{\mathrm{cond}}&=\frac{dx_t}{dt}=\epsilon-x_0\\u_{\mathrm{cond}}&=\frac{x_t-x_0}{t}\quad(0<t<1)\\u_t(x)&=\mathbb E[\epsilon-x_0\mid x_t=x]\end{aligned}`,'Here t=0 is data and t=1 is noise. Generation integrates toward decreasing t. Conditional pairs supply regression targets; their posterior mean supplies the marginal velocity.')+table('Assigned scalar path: clean value 2 and noise −1',['Time','State','Velocity with increasing t'],[['0','2','−3'],['0.5','0.5','−3'],['1','−1','−3']])+p('A negative time increment moves this path toward the clean value. Reversing the time coordinate reverses the velocity sign. Reusing the same sign under both conventions changes the sampler.')+p('The marginal velocity averages over pairs consistent with the observed state. It is not generally the displacement to one original clean sample. FGM v1 equation 3.5 is inconsistent with its equation 3.6 interpolation; the derivative above follows the declared path. '+cite('https://arxiv.org/pdf/2410.19310v1#page=4','Flow Generator Matching §3')+'.'));
 add('shortcut',p('A shortcut model predicts a displacement per unit step at a declared time and step length. Its output can support local movement or a long jump. The step-length input changes the learned function, not just the number of times it is called.')+eq(String.raw`\begin{aligned}x'_{t+d}&=x_t+d\,s_\theta(x_t,t,d)\\s(x_t,t,2d)&=\tfrac12\bigl[s(x_t,t,d)+s(x'_{t+d},t+d,d)\bigr]\end{aligned}`,'Two short displacements compose into one long displacement. Unlike the preceding flow convention, this section uses increasing noise-to-data time: zero is noise and one is data.')+p('The shortcut base target comes from flow matching at infinitesimal step size. Longer targets bootstrap two smaller learned jumps, with stopped target gradients. The second prediction uses the first predicted state and advanced time, not the straight dataset interpolation.')+p('For the toy ODE '+inlineMath(String.raw`x^{\prime}=-x`)+', an exact finite-step displacement is '+inlineMath(String.raw`\frac{x(e^{-d}-1)}d`)+'. Averaging the two consecutive displacements reproduces the 2d displacement exactly. A learned network only approximates this composition.')+p('Joint training avoids separate distillation stages but still incurs bootstrap evaluations and approximation error. '+cite(papers.shortcut,'One Step Diffusion via Shortcut Models')+' defines this distinct approach.'));
 add('shortcut-training',p('The base loss grounds the network in observed noise–data pairs. The bootstrap loss then teaches a longer displacement from two shorter predictions. Use the same noise-to-data convention throughout:')+eq(String.raw`\begin{aligned}x_t&=(1-t)x_{\mathrm{noise}}+t x_{\mathrm{data}}\\y_0&=x_{\mathrm{data}}-x_{\mathrm{noise}}\\x'&=x_t+d\,s_{\mathrm{EMA}}(x_t,t,q)\\y_{2d}&=\operatorname{stopgrad}\!\left[\frac{s_{\mathrm{EMA}}(x_t,t,q)+s_{\mathrm{EMA}}(x',t+d,q)}2\right]\\\ell_{\mathrm{bootstrap}}&=\left\|s_\theta(x_t,t,2d)-y_{2d}\right\|^2\end{aligned}`,'EMA denotes exponential-moving-average parameters. The target has no gradient path. The network still receives gradients through the long-step student prediction.')+p('The recipe uses 75% empirical examples and 25% bootstrap examples. Its eight positive step lengths run from 1/128 to 1 by doubling. For the smallest bootstrap half-step, query the field with q=0; otherwise q=d. The integration distance remains d. Choose grid-aligned times that leave room for both halves.')+code(shortcutTarget.toString())+p('This scalar reference constructs target values only. A tensor implementation must freeze the EMA branch and stop target gradients explicitly. Its callbacks do not implement automatic differentiation, guidance, batching or the training-time sampler.')+table('Synthetic target trace: field output equals state plus time',['Operation','Input state / time','Result'],[['First half-step','2 / 0.25','Velocity 2.25'],['Advance by 0.125','2 + 0.125 × 2.25','State 2.28125'],['Second half-step','2.28125 / 0.375','Velocity 2.65625'],['Long-step target','Average of both velocities','2.453125']])+p('This is our arithmetic example, not a learned flow or image result. Keeping the old time in the second call would instead give 2.390625. The discrepancy isolates why advancing time matters; the predicted midpoint also differs from a new empirical interpolation.')+p('The reported recipe uses EMA decay 0.999, AdamW learning rate 0.0001 and weight decay 0.1. Guidance applies only to zero-step field queries; its scale is chosen before training. Do not apply guidance again to a learned long jump. '+cite('https://arxiv.org/pdf/2410.12557v3#page=5','Shortcut Models v3 §3.1 and Appendix B')+'.')+p('The two target calls affect only the bootstrap quarter. Assuming a backward pass costs two forward passes, an update costs 3.5 forward-equivalent units instead of 3: about 16.7% extra. This is a compute estimate, not a measured runtime guarantee.'));
 add('shortcut-evidence',p('At inference, start from noise at time zero. For N equal steps, call the model with length 1/N, advance the state by that length times its output, then advance time. N=1 needs one call. The trained dyadic budgets do not certify arbitrary untrained step lengths.')+table('Reported ImageNet-256 FID-50k: DiT-B in latent space; lower is better',['Objective','128 calls','4 calls','1 call'],[['Flow matching','17.3','108.2*','324.8*'],['Shortcut','15.5','28.3','40.3'],['Progressive distillation','201.9*','142.5*','35.6']])+p('An asterisk marks a budget the objective was not intended to support. The comparison uses the same architecture and codebase, but baselines can receive greater compute. Shortcut preserves flexible sampling budgets; progressive distillation has the better one-step FID here. One-step shortcut quality does not match its own 128-step quality.')+p('The ImageNet recipe uses batch size 256, 800k updates and guidance scale 1.5. Images are encoded as 32×32×4 latents. Evaluation uses EMA weights and 50k samples against full-dataset statistics. '+cite('https://arxiv.org/pdf/2410.12557v3#page=8','Shortcut Models v3 Table 1 and Appendix B')+'.')+p('The sample grids reuse initial noise within each column. They show approximate preservation of image content across budgets, not pixel identity. Reducing 128 calls to one is not evidence of 128× end-to-end speedup: decoding, launch overhead and hardware still matter.'));
 add('score-distillation',p('Paired distillation preserves a teacher transport. Distribution matching asks a different question: does the student generate the desired population, even if individual noise seeds map differently? A score-based objective can compare smoothed student and target distributions.')+eq(String.raw`\begin{aligned}x_g&=G_\theta(z),\quad x_t=x_g+\sigma_t\epsilon\\D(\theta)&=\mathbb E_{t,x_t\sim p_{\theta,t}}\!\left[w(t)\lVert s_{\theta,t}(x_t)-s_{T,t}(x_t)\rVert^2\right]\end{aligned}`,'A conceptual distributional discrepancy. It is not, by itself, the SiD implementation.')+p('Positive noise makes the student distribution easier to describe with a score. The generator changes both the sampled states and its own marginal score. Differentiating the displayed norm while ignoring either dependence changes the intended gradient.')+p('An auxiliary denoiser can learn the student score from generated examples. Its predictions are estimates, not an analytic score of the generator. Training quality depends on that estimate and its update speed as the generator changes.')+p('Avoiding teacher rollout datasets does not eliminate teacher calls, auxiliary training, or backward passes through input-dependent fields. The saved cost and the new cost must both be measured.'));
 add('sid',p('SiD alternates a generator update with an auxiliary denoiser fitted to corrupted student samples. Its teacher is fixed. The generator loss uses score identities and a fused objective rather than only the score-difference norm.')+eq(String.raw`\begin{aligned}\Delta&=D_{\mathrm{teacher}}(x_t,t)-D_{\mathrm{aux}}(x_t,t)\\\ell_{\mathrm{gen}}&=\frac{\omega(t)}{\sigma_t^4}\Bigl[(1-\lambda)\lVert\Delta\rVert^2\\&\qquad+\Delta^\top(D_{\mathrm{aux}}(x_t,t)-x_g)\Bigr]\end{aligned}`,'Per-sample term from SiD equation 23; the training loss averages over the stated samples and noise levels, with its mixing coefficient renamed λ to avoid conflict with the DDPM schedule. Dteacher and Daux predict denoised data in additive-noise coordinates.')+p('The original method retains derivatives of both denoisers with respect to xₜ during the generator update. Freezing their parameters is not detaching their outputs. The auxiliary update uses generated-data denoising targets; the generator update uses the fused loss.')+p('Weights, noise sampling and gradient routing are essential. An arbitrary stop-gradient placement produces a different algorithm. The identity objective does not imply every variant uses a GAN discriminator. '+cite(papers.sid,'Score identity Distillation, §4 and Algorithm 1')+' is the implementation reference.'));
 add('sid-gradient-example',p('Why is a good auxiliary estimate not enough? Consider scalar Gaussian data with mean zero and unit variance. The generator shifts that mean by θ. Its auxiliary denoiser has a separate mean parameter ψ, held fixed during the generator update.')+eq(String.raw`\begin{aligned}x_g&=\theta+z,\quad x_t=x_g+\sigma\epsilon,\quad v=1+\sigma^2\\D_T(u)&=\frac{u}{v},\quad D_A(u)=\frac{u+\psi\sigma^2}{v}\\L_{\mathrm{ideal}}&=\frac{\theta^2}{v^2},\quad L_{\mathrm{naive}}=\frac{\psi^2}{v^2}\\\mathbb E[\ell_{\mathrm{fused}}]&=\frac{\psi\theta-\lambda\psi^2}{v^2}\\\partial_\theta L_{\mathrm{ideal}}&=\frac{2\theta}{v^2},\quad \left.\partial_\theta L_{\mathrm{naive}}\right|_\psi=0\\\left.\partial_\theta\mathbb E[\ell_{\mathrm{fused}}]\right|_\psi&=\frac{\psi}{v^2}\end{aligned}`,'Independent standard-normal z and ε; positive σ; constant assigned weight ω=1. Expectations include generator and corruption noise. The derivatives hold ψ, σ and λ fixed, except that the ideal objective uses the true moving generator score.')+p('The denoiser difference is constant in its input. Its squared norm therefore gives no generator gradient. Setting ψ numerically equal to θ does not connect their computation graphs. The fused cross term restores a dependence on the generated sample.')+table('Gaussian counterexample: θ=ψ=2, σ=1 and λ=1; constant weight, not measured training',['Objective','Expected value','Generator derivative'],[['Ideal moving-score discrepancy','1','1'],['Naive fixed-auxiliary norm','1','0'],['Fused SiD term','0','0.5']])+p('Equal values can hide different gradients; a zero surrogate value can still provide an update. Here the positive derivative moves the generator mean toward zero under gradient descent. Its scale need not match the ideal discrepancy.')+p('Freeze denoiser weights, but retain both denoisers’ input derivatives. Do not infer that λ is irrelevant in neural training from this affine example. The paper uses a different, detached adaptive weight; the constant weight here isolates the gradient mechanism. '+cite('https://arxiv.org/html/2404.04057v2#A4','SiD Appendix D')+' supplies the Gaussian setup; the table evaluates equation 23 with the stated constant weight.'));
 add('sid-recipe',p('Both trainable networks start from pretrained EDM weights. Data-free distillation does not remove pretraining or evaluation data. Update the auxiliary denoiser first, with generated targets and EDM’s denoising sampler and weighting:')+eq(String.raw`L_\psi=\mathbb E\!\left[\gamma(t)\lVert D_\psi(x_g+\sigma_t\epsilon,t)-x_g\rVert^2\right]`,'Hold the generator fixed for this auxiliary update. Then update the generator with the fused loss, retaining denoiser input derivatives.')+eq(String.raw`\begin{aligned}\omega(t)&=\frac{C\sigma_t^4}{\operatorname{sg}(\lVert x_g-D_T(x_t,t)\rVert_1)}\\\sigma_t&=\left[\sigma_{\min}^{1/\rho}+t(\sigma_{\max}^{1/\rho}-\sigma_{\min}^{1/\rho})\right]^\rho\end{aligned}`,'Generator step: uniform t on [0,0.8]; σmin=0.002, σmax=80, ρ=7. C is the paper’s total pixel count; sg stops gradients. Generator input-noise scale: 2.5.')+p('Handle zero or nonfinite denominators explicitly; the displayed expression supplies no safeguard. Do not silently introduce epsilon clipping. The released denominator floor is explicit in the next section.')+code(sidGeneratorNoise.toString())+table('Computed generator noise levels, not measured training',['Assigned t','Noise standard deviation'],[0,.4,.8].map(t=>[String(t),sidGeneratorNoise(t).toFixed(6)]))+p(cite('https://arxiv.org/pdf/2404.04057v2#page=16','SiD Algorithm 1')+'; '+cite('https://arxiv.org/pdf/2404.04057v2#page=6','equations 25–26')+'.'));
 add('sid-implementation',p('The pinned main-branch implementation is SiD, not the separate adversarial SiDA branch. It cancels the explicit fourth power of noise through the chosen weight. The denominator becomes a stopped mean absolute residual across channels and spatial coordinates:')+eq(String.raw`\begin{aligned}\Delta_i&=D_{T,i}-D_{A,i}\\m&=\operatorname{sg}\!\left(\max\left(10^{-5},\frac1K\sum_{i=1}^{K}|y_i-D_{T,i}|\right)\right)\\\ell_{\mathrm{released}}&=\sum_{i=1}^{K}\frac{\Delta_i[(1-\lambda)\Delta_i+D_{A,i}-y_i]}{m}\end{aligned}`,'One image y has K=C×H×W coordinates. The source computes the denominator in float32. Keep its value detached while differentiating the numerator. The floor changes the paper expression near zero residual.')+p('The loop sums coordinate losses, then scales by the per-rank total batch size and the configured loss scale. Replacing this sum with a pixel mean changes gradient magnitude. Microbatches accumulate before each optimizer step.')+p('This finite-scalar adaptation checks loss values only. It does not implement autograd, float32 rounding or the release’s NaN-sample filtering:')+code(sidCoordinateLoss.toString())+table('Assigned two-coordinate example: teacher [1,1], auxiliary [0,0], mixing 1.2',['Generated coordinates','Stopped denominator','Coordinate-summed loss'],[[ '[0,2]',sidCoordinateLoss([0,2],[1,1],[0,0]).scale.toFixed(5),sidCoordinateLoss([0,2],[1,1],[0,0]).loss.toFixed(1)],['[1,1]',sidCoordinateLoss([1,1],[1,1],[0,0]).scale.toFixed(5),sidCoordinateLoss([1,1],[1,1],[0,0]).loss.toFixed(0)]])+p('The small floor prevents division by zero; it does not bound the loss or gradient. Rejecting nonfinite inputs here is stricter than dropping NaN samples. Audit the all-filtered batch case before treating that release path as robust.')+table('Released update ownership',['Phase','Trainable parameters','Mode and data flow'],[['Auxiliary update','Auxiliary only','Generator frozen/eval; fresh generated images; auxiliary train mode and augmentation'],['Generator update','Generator only','Teacher and auxiliary frozen/eval; fresh images and corruption; denoiser input gradients stay live'],['Evaluation','None','Generator EMA; one preconditioned call at the fixed input noise scale']])+eq(String.raw`\begin{aligned}\log\sigma_{\mathrm{aux}}&=-1.2+1.2Z,\quad Z\sim\mathcal N(0,1)\\\gamma(\sigma_{\mathrm{aux}})&=\frac{\sigma_{\mathrm{aux}}^2+0.5^2}{(\sigma_{\mathrm{aux}}\,0.5)^2}\end{aligned}`,'Auxiliary-loss defaults: log-normal noise and data standard deviation 0.5. This distribution is not the generator’s bounded uniform-time schedule.')+p('The runner still reads a dataset for shapes, class labels, sample grids and evaluation. Image pixels are overwritten by generated samples before the loss. Data-free objectives therefore do not imply a dataset-independent launch script.')+p('The FFHQ launch uses generator Adam β₁=0.9, agreeing with Table 6 rather than Appendix A’s value 1. '+cite('https://github.com/mingyuanzhou/SiD/blob/01fbb13cf18411e5f70d187c8fb2559567e5ae1c/training/sid_loss.py','Pinned loss')+'; '+cite('https://github.com/mingyuanzhou/SiD/blob/01fbb13cf18411e5f70d187c8fb2559567e5ae1c/training/sid_training_loop.py','update loop')+'; '+cite('https://github.com/mingyuanzhou/SiD/blob/01fbb13cf18411e5f70d187c8fb2559567e5ae1c/run_sid.sh','launch recipes')+'.'));
 add('sid-evidence',p('FID uses 50k images and the teacher-training reference set. Evaluate EMA checkpoints every 500k synthetic images and select the lowest FID. Ten re-evaluations are not ten independent training runs.')+table('Reported FID: lower is better; SiD uses one evaluation',['Dataset','Teacher NFE / FID','SiD λ=1','SiD λ=1.2'],[['CIFAR-10 unconditional','35 / 1.97','2.028 ± 0.020','1.923 ± 0.017'],['ImageNet-64 conditional','511 / 1.36','2.022 ± 0.031','1.524 ± 0.009'],['ImageNet-64 conditional','79 / 2.64','Same student','Same student']])+p('Training uses 500M synthetic images, extended to 1B for ImageNet with λ=1.2. ImageNet’s batch increase from 1024 to 8192 also lowered the learning rate from 5e−6 to 4e−6. FP16 is a suspected cause, not an established diagnosis. Figures 4/9 show spikes. Log–log linearity indicates power-law behavior, not exponential convergence. Table 6 excludes FID-evaluation cost. '+cite('https://arxiv.org/pdf/2404.04057v2#page=8','SiD Tables 1/3 and Figures 4/9')+'; '+cite('https://arxiv.org/pdf/2404.04057v2#page=14','Appendices A/E')+'.'));
 add('fgm',p('Flow Generator Matching (FGM) extends the distribution-matching viewpoint to induced flow fields. A generator’s noised/interpolated population has an implicit marginal velocity. An auxiliary model estimates that field from conditional flow targets.')+eq(String.raw`\begin{aligned}J&=\mathbb E\lVert u_T(x_t,t)-v_\theta(x_t,t)\rVert^2\\L_1&=\mathbb E\lVert u_T-v_{\mathrm{sg}}\rVert^2\\L_2&=\mathbb E[2(u_T-v_{\mathrm{sg}})^\top(v_{\mathrm{sg}}-u_{\mathrm{cond}})]\end{aligned}`,'FGM derives a gradient-equivalent surrogate under regularity. vsg stops generator-parameter dependence in the estimated field, not its input derivative; ucond is the known conditional velocity.')+p('The second term accounts for a dependence that naive frozen-field matching omits. The theoretical full surrogate and the practical recipe are not identical: the paper drops L₁ in its CIFAR-10 and text-to-image experiments because of instability.')+p('FGM is not a claim that the one-step generator executes a teacher ODE. It trains a population through vector-field identities. '+cite(papers.fgm,'Flow Generator Matching, §4–5')+' explains the derivation and practical modification.'));
 add('fgm-gradient',p('Reuse the mean-shift idea from the SiD example, but now use the linear flow path. Real clean data has mean zero and variance one. Generated clean data has mean θ and variance one. An exact auxiliary field at the current generator mean still needs the correct derivative contract.')+eq(String.raw`\begin{aligned}V_t&=(1-t)^2+t^2,\quad a_t=\frac{2t-1}{V_t}\\u_T(x,t)&=a_tx,\quad v_\psi(x,t)=a_tx-\frac{t\psi}{V_t}\\J(\theta)&=\frac{t^2\theta^2}{V_t^2},\quad L_1=\frac{t^2\psi^2}{V_t^2}\\L_2&=\frac{2t^2\psi(\theta-\psi)}{V_t^2}\\\partial_\theta J&=\frac{2t^2\theta}{V_t^2},\quad \left.\partial_\theta L_1\right|_\psi=0\\\left.\partial_\theta L_2\right|_\psi&=\frac{2t^2\psi}{V_t^2}\end{aligned}`,'Independent unit Gaussian generator/corruption noises; interior time; fixed auxiliary mean ψ during the update. Loss values are expectations. These exact Gaussian calculations are our explanatory example, not reported training measurements.')+table('Mean-shift example: θ=ψ=2 and t=0.5',['Objective','Expected value','Generator derivative'],[['Ideal moving-field discrepancy',fgmMeanCase(2,2,.5).ideal.toFixed(0),fgmMeanCase(2,2,.5).idealGradient.toFixed(0)],['Fixed-auxiliary matching',fgmMeanCase(2,2,.5).naive.toFixed(0),'0'],['FGM correction',fgmMeanCase(2,2,.5).correction.toFixed(0),fgmMeanCase(2,2,.5).correctionGradient.toFixed(0)]])+p('Both marginal fields have the same input slope. Their difference is constant, so moving generated inputs gives no gradient through the naive norm. The conditional velocity still depends on the generated clean sample. FGM’s product identity uses that dependence to recover the missing term.')+p('At an exact auxiliary fit, the correction recovers the ideal derivative in this example. This does not prove that dropping the first term is correct for arbitrary neural fields. Approximate auxiliary fits and modified training losses remain separate assumptions. '+cite('https://arxiv.org/pdf/2410.19310v1#page=16','FGM Appendix A')+'.'));
 add('fgm-evidence',table('CIFAR-10 FID: teacher inference budget changes the comparison',['Setting','Teacher: 50 steps','Teacher: 100 steps','FGM: one step'],[['Unconditional','3.67','2.93','3.08'],['Conditional','3.66','2.87','2.58']])+p('Table 4 reports 20M training images, batch 512 and Adam at 2e−5. The CIFAR distillation recipe uses logit-normal times, not Algorithm 1’s uniform-time example.')+p('The SD3-Medium recipe adds GAN training on roughly 500k synthetic images and omits the first FGM term. Its result is not evidence for the unmodified data-free theoretical objective. Generator and auxiliary losses use different timestep distributions.')+eq(String.raw`\widehat x_0=z-0.97\,v_\theta(0.8z,0.97),\quad z\sim\mathcal N(0,I)`,'Text-to-image parameterization from Appendix B.2. Input scaling and network time are separate choices; this is not a generic Euler step for every flow.')+p('GenEval reports 0.65 for the one-step model versus 0.70 for 28-step SD3. Evaluation uses four images per prompt at 1024px and model-specific guidance. Fewer steps are not a measured end-to-end latency ratio. '+cite('https://arxiv.org/pdf/2410.19310v1#page=8','FGM Tables 1–2')+'; '+cite('https://arxiv.org/pdf/2410.19310v1#page=10','Table 3')+'; '+cite('https://arxiv.org/pdf/2410.19310v1#page=17','Appendix B')+'.'));
 add('corruptions',p('The broad design pattern is to define corruption and learn recovery. Gaussian noise is one choice. Masking, token replacement, deletion, blurring and partial observation expose different missing-information tasks.')+p('The connection is conceptual until a process and an objective are specified. A masked language-model predictor is not automatically a normalized iterative generator. A blur may erase information without becoming a simple known terminal prior.')+p('Discrete token probabilities do not have the ordinary Euclidean gradient used by a continuous Gaussian score. They need discrete transition kernels, reverse conditional probabilities or another declared probability path. Autoregressive generation can also be viewed through ordered partial observation, but its factorization is different.')+p('A diffusion drafter for language-model speculation belongs to '+related('execution/speculation','Speculative Decoding')+'. That note owns verification and token-level acceleration. The Gaussian image equations here must not be transferred to such a drafter without a discrete-process derivation.'));
 add('choice',table('Match the bottleneck to the intervention',['Intervention','Learning target','Main new cost or constraint'],[['Better solver','Keep the current field','More complex integration and schedule tuning'],['Paired one-step distillation','Teacher endpoint for a declared seed','Teacher rollout targets and global-map capacity'],['Progressive distillation','Two teacher updates per student update','Repeated stages and accumulated approximation'],['Consistency distillation/training','Shared trajectory endpoint with boundary','Target construction, discretization and stability'],['Shortcut model','Step-conditioned displacement','Bootstrap calls and long-jump approximation'],['SiD / FGM','Smoothed population fields and identities','Auxiliary field estimation and gradient routing']])+p('There is no universal ordering from low to high training complexity. A large frozen teacher plus an auxiliary model can dominate memory. A costly offline teacher dataset can dominate paired training. A solver change can be cheap to develop yet fail at the desired evaluation budget.')+p('Compare quality at matched conditioning, resolutions, data and evaluation settings. Include diversity, coverage, prompt alignment and artifact rates, not only visual sharpness. A teacher checkpoint and its sampling configuration together define the target.')+p('The Score-SDE comparisons illustrate why settings matter. Table 3 selects the lowest-FID checkpoint and uses predictor–corrector sampling. Table 2 uses the final checkpoint and black-box ODE sampling. Do not attribute every difference to the SDE alone. Appendix H’s architecture exploration also uses different checkpoint windows for VE and VP models. '+cite('https://arxiv.org/html/2011.13456v2','Score-SDE §4.4 and Appendix H')+'.'));
 add('implementation',p('The first useful kernel is a direct training sample. The schedule lookup must return batch-shaped coefficients with the correct signal/noise convention. The following is pseudocode, not a complete training loop.')+code('t = sample_noise_level(batch_size)\na, sigma = schedule(t)  # reshape for coordinate broadcasting\neps = randn_like(clean)\nnoisy = a * clean + sigma * eps\nprediction = denoiser(noisy, t, condition)\nper_example = squared_error(prediction, eps).mean(data_axes)\nloss = (time_weight(t) * per_example).mean()')+p('For additive-noise score checks, test the analytic posterior identity before adding a neural field. For a DDPM sampler, test the posterior coefficients, noise conversion, schedule indexing and final-step convention on a known Gaussian population.')+'<h3>Make the ancestral last step explicit</h3>'+p('This tested scalar JavaScript kernel accepts cumulative alpha at the previous level, the current beta, state x, predicted noise eps and standard-normal draw z. The kernel rejects nonfinite inputs. A tensor implementation must broadcast schedule values and preserve data shapes.')+code(ancestralStep.toString())+p('Previous cumulative alpha equals one at t=1. The kernel then returns the mean without fresh noise, including when mode selects beta variance. The two fixed variance choices are not the forward marginal variance. A likelihood calculation still needs its separate decoder convention. '+cite('https://arxiv.org/html/2006.11239v2','DDPM §3.2–3.3 and Algorithm 2')+'.')+p('This kernel implements the unclipped equation, not the complete released image sampler. The original TensorFlow code first converts predicted noise into a clean-image estimate. By default, it clips that estimate to [−1, 1], then computes the posterior mean. Clipping can change the update; it depends on the data range and is not a universal rule for latent states.')+p('The released implementation uses posterior variance and zero-based schedule indices. Code index 0 means one forward corruption step; the final reverse update therefore masks fresh noise at index 0. The paper calls that step t=1. Schedule coefficients are calculated in float64, then stored as TensorFlow constants in the selected dtype. '+cite('https://github.com/hojonathanho/diffusion/blob/master/diffusion_tf/diffusion_utils.py','Released DDPM sampling implementation')+'.')+code('dt = next_time - time  # negative in this convention\nscore = score_model(x, time)\ndrift = forward_drift(x, time) - diffusion(time)**2 * score\nx = x + drift * dt + diffusion(time) * sqrt(-dt) * randn_like(x)')+p('This is a schematic Euler–Maruyama reverse-SDE update. It assumes scalar state-independent diffusion and dt<0. Removing the random term does not make it the probability-flow update; halve the score coefficient for that ODE.')+p('Distillation tests must include gradient ownership. Confirm which parameters update and whether teacher/auxiliary input derivatives remain live. Check schedule endpoints, nonfinite values, tiny denominators and loss-weight scales. First validate a low-dimensional known distribution; then evaluate real-data generation.'));
 add('history',table('Selected first-publication chronology, not an invention claim',['Year','Contribution','Branch'],[['2020','DDPM: useful Gaussian reverse training and noise prediction','Discrete diffusion'],['2020','DDIM: non-Markovian construction and fast deterministic sampling','Sampler construction'],['2020','Score SDE framework: reverse SDE and probability-flow ODE','Continuous unification'],['2022','Progressive Distillation','Staged trajectory compression'],['2023','Consistency Models','Direct endpoint map, with training or distillation'],['2024, April','SiD','Data-free distributional score identities'],['2024, October','Shortcut Models','Joint local flow and step-conditioned bootstrap'],['2024, October','Flow Generator Matching','Distribution matching through implicit velocities']])+p('These branches coexist. A newer generator objective does not replace numerical solvers for every task. Diffusion probabilistic models and score matching also predate DDPM; the table tracks this note’s method sequence, not the full history of generative modeling.')+p('The practical progression is local prediction → reliable transport → fewer evaluations. Each acceleration method chooses a different object to preserve: field, trajectory endpoint, composed displacement, or output population.'));
 add('sources',p(Object.entries(papers).map(([k,url])=>cite(url,k==='fgm'?'Flow Generator Matching':k==='sid'?'Score identity Distillation':k==='sde'?'Score SDE':k)).join(' · '))+p('Su Jianlin’s original series references: '+[9119,9152,9209,9262,9509,10085,10567,10617,10633].map(n=>cite('https://kexue.fm/archives/'+n,'Article '+n)).join(' · '))+p(related('post-training/distillation','Distillation')+' · '+related('training/objectives','Losses and Objectives')+' · '+related('math/probability','Probability')+' · '+related('math/calculus','Calculus')+' · '+related('math/information','Information Theory')+' · '+related('execution/speculation','Speculative Decoding'))+p('All four interactive examples use exact synthetic distributions or known scalar dynamics. None runs a trained image generator or displays measured generation quality.'));
 return topic(diffusionMeta,diffusionSections,'Learn local denoising fields, then choose what a faster generator should preserve.',parts.join('\n'));}
export function mountDiffusion(scope=document){mountTopic(scope,diffusionMeta.slug,mountDiffusionScenes);}
diffusionMeta.searchText=diffusionReader(()=>'').replace(/<[^>]*>/g,' ');
